impl UsageProvider {
    pub const ALL: [Self; 6] = [
        Self::Anthropic,
        Self::OpenAi,
        Self::ZAi,
        Self::Lefine,
        Self::Gemini,
        Self::Qwen,
    ];

    #[must_use]
    pub const fn as_str(self) -> &'static str {
        match self {
            Self::Anthropic => "anthropic",
            Self::OpenAi => "openai",
            Self::ZAi => "z-ai",
            Self::Lefine => "lefine",
            Self::Gemini => "gemini",
            Self::Qwen => "qwen",
        }
    }

    pub(super) const fn subscription(self) -> Option<SubscriptionProvider> {
        match self {
            Self::Anthropic => Some(SubscriptionProvider::Claude),
            Self::OpenAi => Some(SubscriptionProvider::Codex),
            Self::Gemini => Some(SubscriptionProvider::Gemini),
            Self::Qwen => Some(SubscriptionProvider::Qwen),
            Self::ZAi | Self::Lefine => None,
        }
    }
}

#[derive(Clone, Debug, Deserialize, Serialize, schemars::JsonSchema)]
pub struct UsageEnvelope {
    pub schema_version: u8,
    pub subscriptions: Vec<SubscriptionUsage>,
}

#[derive(Clone, Debug, Deserialize, Serialize, schemars::JsonSchema)]
pub struct UsagePool {
    pub configured_accounts: usize,
    pub contributing_accounts: usize,
    pub unavailable_accounts: usize,
    /// Accounts the router holds out of rotation on a vendor rate limit
    /// (issue #677). Absent when not reported.
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub cooling_down_accounts: Option<usize>,
    /// Accounts paused by an operator or by `ACCOUNT_PAUSE_AT_PERCENT`.
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub paused_accounts: Option<usize>,
    /// Per-model cooldowns across the pool, where only one model was limited.
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub model_cooldowns: Option<usize>,
}

#[derive(Clone, Debug, Deserialize, Serialize, schemars::JsonSchema)]
pub struct UsageWindow {
    pub name: String,
    #[serde(skip_serializing_if = "Option::is_none")]
    pub used_percentage: Option<f64>,
    #[serde(skip_serializing_if = "Option::is_none")]
    pub remaining_percentage: Option<f64>,
    #[serde(skip_serializing_if = "Option::is_none")]
    pub resets_at: Option<String>,
    #[serde(skip_serializing_if = "Option::is_none")]
    pub window_seconds: Option<u64>,
    /// Number of pool accounts that supplied comparable percentages for this
    /// aggregate window.
    #[serde(skip_serializing_if = "Option::is_none")]
    pub contributors: Option<usize>,
    /// Distinct provider reset times when pooled accounts disagree. In that
    /// case `resets_at` stays absent rather than inventing one timestamp.
    #[serde(default, skip_serializing_if = "Vec::is_empty")]
    pub reset_times: Vec<String>,
}
